const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;
const body = $input.first().json.body ?? {};
const batchId = typeof body.batch_id === 'string' ? body.batch_id : '';
return [{ json: { batch_id: batchId, batch_id_valid: UUID.test(batchId) } }];

const HIGH_CONFIDENCE_CUTOFF = 0.7;
const AFFORDABILITY_CAP = 0.65;
const INDICATIVE_LOAN_RUPEES = 500000;
const INDICATIVE_TENURE_MONTHS = 60;

function rupees(amount) {
  return '₹' + Math.round(amount).toLocaleString('en-IN');
}

function monthlyEmi(principal, annualRatePct, months) {
  const monthlyRate = annualRatePct / 1200;
  if (monthlyRate === 0) {
    return principal / months;
  }
  const growth = (1 + monthlyRate) ** months;
  return (principal * monthlyRate * growth) / (growth - 1);
}

function publishedRate(product) {
  if (product.interest_rate_max !== null && product.interest_rate_max !== undefined) {
    return { pct: Number(product.interest_rate_max), basis: 'top published rate' };
  }
  if (product.interest_rate_min !== null && product.interest_rate_min !== undefined) {
    return { pct: Number(product.interest_rate_min), basis: 'published starting rate' };
  }
  return null;
}

function affordability(product) {
  const rate = publishedRate(product);
  if (rate === null) {
    return { indicative_emi: null, emi_note: null };
  }
  const emi = Math.round(monthlyEmi(INDICATIVE_LOAN_RUPEES, rate.pct, INDICATIVE_TENURE_MONTHS) * 100) / 100;
  return {
    indicative_emi: emi,
    emi_note: `indicative EMI ${rupees(emi)} for ${rupees(INDICATIVE_LOAN_RUPEES)} over ${INDICATIVE_TENURE_MONTHS} months at the ${rate.basis} of ${rate.pct}% p.a.`,
  };
}

function ruleCard(product) {
  const confidence = product.parse_confidence === null ? 0 : Number(product.parse_confidence);
  const fullyStructured = confidence >= HIGH_CONFIDENCE_CUTOFF;
  return {
    product_id: Number(product.product_id),
    parse_confidence: confidence,
    near_miss_policy: fullyStructured ? 'clear_reject' : 'borderline',
    affordability_cap: AFFORDABILITY_CAP,
    ...affordability(product),
    conditions_note: fullyStructured
      ? null
      : `The lender's criteria are only partly captured in structured fields (parse confidence ${confidence.toFixed(2)}), so this is indicative; the lender's full conditions still apply.`,
  };
}

const run = $input.first().json;

return [
  {
    json: {
      run_id: run.run_id,
      batch_id: run.batch_id,
      stage2_started_at: run.stage2_started_at,
      cards: (run.products || []).map(ruleCard),
    },
  },
];
